function e(t){return new Intl.NumberFormat("vi-VN",{style:"currency",currency:"VND",minimumFractionDigits:0}).format(t).replace("₫","₫").trim()}function i(t){if(!t)return"--/--/----";const r=new Date(t);return isNaN(r.getTime())?"--/--/----":new Intl.DateTimeFormat("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"}).format(r)}function n(t){if(!t)return"--/--/---- --:--";const r=new Date(t);return isNaN(r.getTime())?"--/--/---- --:--":new Intl.DateTimeFormat("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(r)}function a(t){return new Intl.NumberFormat("vi-VN").format(t)}export{i as a,n as b,a as c,e as f};
